marks = {"three_step": "square*", "chirho": "diamond*", "dowhy": "triangle*", "causalai": "pentagon*", "twin": "*"}
msize = {"three_step": 2.2, "chirho": 2.9, "dowhy": 2.9, "causalai": 2.7, "twin": 2.4}
US_TICKS2 = r"ytick={10,100,1000,10000,100000}, yticklabels={10\,$\mu$s,100\,$\mu$s,1\,ms,10\,ms,100\,ms}"
pm = J("per_model.json")
FAMS = ["GBR", "HGB", "LGBM", "RF", "XGB"]
def superplot(groups, labels, width, height, sep=0.17, jit=0.018):
    """Cell style: in each group, every method is a column of points (a model, or a table) and a black line at their mean."""
    n = len(groups)
    ticks = ["{%s\\\\\\textcolor{ctwin}{\\bfseries %.0f$\\times$}}" % (l, sum(g["three_step"]) / sum(g["twin"])) for l, g in zip(labels, groups)]
    b = [r"\begin{axis}[nat, width=%s, height=%s, ymode=log, ymin=2, ymax=1e6, ytick={10,100,1000,10000,100000,1000000}," % (width, height),
         r"  yticklabels={10\,$\mu$s,100\,$\mu$s,1\,ms,10\,ms,100\,ms,1\,s}, xmin=0.45, xmax=%g, xtick={1,...,%d}, xticklabels={%s}," % (n + 0.55, n, ",".join(ticks)),
         r"  xticklabel style={align=center}, xtick style={draw=none}, ylabel={Mean time per query}, legend style={at={(0,1.02)}, anchor=south west}, legend columns=-1]"]
    for k, col, name in M5:
        b.append(r"\addlegendimage{only marks, mark=%s, mark size=2.2pt, mark options={%s}}" % (marks[k], "mkours" if k == "twin" else "mk=" + col))
    b.append(r"\legend{" + ",".join(nm for _, _, nm in M5) + "}")
    for i in range(1, n + 1, 2):  # a light band behind every other group
        b.append(r"\fill[cband] (axis cs:%g,2) rectangle (axis cs:%g,1e6);" % (i - 0.5, i + 0.5))
    for i, g in enumerate(groups, 1):
        for j, (k, col, _) in enumerate(M5):
            x, vals = i + (j - 2) * sep, g[k]
            m = len(vals)
            pts = " ".join("(%.3f,%.5g)" % (x + (t - (m - 1) / 2) * jit * 5 / max(m, 5), v) for t, v in enumerate(vals))
            b.append(r"\addplot[only marks, forget plot, mark=%s, mark size=1.5pt, mark options={%s}] coordinates {%s};" % (marks[k], "mkours" if k == "twin" else "mk=" + col, pts))
            mean = sum(vals) / m
            b.append(r"\draw[cink, line width=0.9pt] (axis cs:%.3f,%.5g) -- (axis cs:%.3f,%.5g);" % (x - sep * 0.42, mean, x + sep * 0.42, mean))
    b.append(r"\end{axis}")
    return b
